from pathlib import Path
import json,hashlib,sys,zipfile,xml.etree.ElementTree as ET
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'engine'));D=R/'docs/v101-ux'
load=lambda p:json.loads((D/p).read_text(encoding='utf8'))
old=json.loads((R/'docs/v101/CODE_FREEZE.json').read_text(encoding='utf8'))
checkpoint=load('checkpoint.json');assert hashlib.sha256((R/'docs/v101/candidate-code-v101.zip').read_bytes()).hexdigest()==checkpoint['v101_archive_sha256'];assert hashlib.sha256((R/'docs/v100/candidate-code-r2.zip').read_bytes()).hexdigest()==checkpoint['r2_archive_sha256']
changed=[];unchanged=[]
for row in old['files']:
 actual=hashlib.sha256((R/row['path']).read_bytes()).hexdigest();entry={'path':row['path'],'previous_sha256':row['sha256'],'sha256':actual}
 (changed if actual!=row['sha256'] else unchanged).append(entry)
assert {x['path'] for x in changed}=={'engine/vigile/web/index.html','engine/vigile/web/app.js','engine/vigile/web/management.js','engine/vigile/web/style.css','engine/tests/management_ui_unit.cjs'}
new=['engine/tools/demo_astronaut_v101.py','engine/tests/test_astronaut_ux_v101.py','engine/tests/astronaut_ui_unit.cjs']
added=[{'path':p,'sha256':hashlib.sha256((R/p).read_bytes()).hexdigest()} for p in new]
(D/'CHANGE_MANIFEST.json').write_text(json.dumps({'modified':changed,'added':added,'unchanged_files':unchanged,'no_engine_python_or_clinical_knowledge_changes':True},indent=2),encoding='utf8')
files=[{'path':p,'sha256':hashlib.sha256((R/p).read_bytes()).hexdigest()} for p in sorted({x['path'] for x in old['files']}|set(new))]
with zipfile.ZipFile(D/'candidate-code-v101-ux.zip','x',zipfile.ZIP_DEFLATED) as z:
 for f in files:z.write(R/f['path'],f['path'])
with zipfile.ZipFile(D/'candidate-code-v101-ux.zip') as z:assert all(hashlib.sha256(z.read(f['path'])).hexdigest()==f['sha256'] for f in files)
implementation_hash=old['implementation_hash'];assert implementation_hash==load('mission-verification.json')['implementation_hash']
freeze={'variant':'VIGILE_1.0.1_ASTRONAUT_UX','date':'2026-11-02','runtime_implementation_hash_unchanged':implementation_hash,'archive':'candidate-code-v101-ux.zip','sha256':hashlib.sha256((D/'candidate-code-v101-ux.zip').read_bytes()).hexdigest(),'files':files,'requires_original_corpus':True,'contains_database_credentials_models':False}
(D/'CODE_FREEZE_UX.json').write_text(json.dumps(freeze,indent=2),encoding='utf8')
from vigile.local_protection import verified_backup,restrict_directory
backup=verified_backup(R/'engine/data/mission-v101-astronaut/vigile.sqlite3',R/'work/v101-ux/astronaut-db-backup');restrict_directory(R/'work/v101-ux/astronaut-db-backup');(D/'demo-backup.json').write_text(json.dumps(backup,indent=2),encoding='utf8')
