assert suite.attrib['tests']=='692' and all(suite.attrib[x]=='0' for x in ['failures','errors','skipped']);assert target.attrib['tests']=='59' and target.attrib['failures']=='0'
verification=load('mission-verification.json');offline=load('offline-modes.json');http=load('http-and-invariance.json')
